parameters.query:
BEGIN;

WITH sessoes_alvo AS (
  SELECT id
  FROM unifag_bot.sessoes_atendimento
  WHERE telefone = '5511934366104'
),
mensagens_alvo AS (
  SELECT
    hm.id,
    hm.metadata->>'message_id' AS message_id
  FROM unifag_bot.historico_mensagens hm
  WHERE hm.sessao_id IN (SELECT id FROM sessoes_alvo)
)
DELETE FROM unifag_bot.processed_messages
WHERE message_id IN (
  SELECT message_id
  FROM mensagens_alvo
  WHERE message_id IS NOT NULL
);

DELETE FROM unifag_bot.historico_mensagens
WHERE sessao_id IN (
  SELECT id
  FROM unifag_bot.sessoes_atendimento
  WHERE telefone = '5511934366104'
);

DELETE FROM unifag_bot.sessoes_atendimento
WHERE telefone = '5511934366104';

COMMIT;

