const raw = $json.output ?? $json;

let out = raw;

if (typeof out === 'string') {
  let cleaned = out.trim();

  // remove bloco ```json ... ```
  cleaned = cleaned.replace(/^```json\s*/i, '').replace(/^```\s*/i, '');
  cleaned = cleaned.replace(/\s*```$/i, '').trim();

  try {
    out = JSON.parse(cleaned);
  } catch (e) {
    out = { say: String(cleaned) };
  }
}

const bottext =
  out?.say ??
  out?.reply ??
  out?.text ??
  out?.message ??
  (typeof out === 'string' ? out : JSON.stringify(out));

const bot_text = String(bottext).replace(/\r?\n/g, '\n').trim();
const bot_text_escaped = bot_text.replace(/\r?\n/g, '\n');

const edit = $('Edit Fields').item.json;
const dbSession = $('DB - Get Session').item.json || {};

let contexto = dbSession.contexto ?? {};
if (typeof contexto === 'string') {
  try {
    contexto = JSON.parse(contexto);
  } catch (e) {
    contexto = {};
  }
}

return [
  {
    json: {
      ...edit,
      bot_text,
      bot_text_escaped,
      handoff: out?.handoff?.to_human ?? false,
      handoff_reason: out?.handoff?.reason || 'sem_motivo',
      next_stage: out?.etapa || 'sem_etapa',
      action_type: out?.action?.type || 'none',
      action_payload: out?.action?.payload || {},
      agent_raw: out,

      campanha_nome: contexto?.campanha_nome || "",
      template: contexto?.template || "",
      message_text: contexto?.message_text || "",
    }
  }
];

