const ctx = $json.contexto || {};
const historico = Array.isArray(ctx.historico_qa) ? ctx.historico_qa : [];

const historicoTexto = historico
  .map((item, index) => {
    const pergunta = String(item?.pergunta || '').replace(/\r?\n/g, ' ').replace(/\s+/g, ' ').trim();
    const resposta = String(item?.resposta || '').replace(/\r?\n/g, ' ').replace(/\s+/g, ' ').trim();

    if (!pergunta) {
      return `${index + 1}. ${resposta}`;
    }

    return `${index + 1}. ${pergunta} => ${resposta}`;
  })
  .join(' | ');

return [
  {
    json: {
      session_id: $json.id || '',
      telefone: $json.telefone || ctx.wa_id || '',
      campanha_nome: ctx.campanha_nome || '',
      template: ctx.template || '',
      message_text: ctx.message_text || '',
      motivo_handoff: ctx.motivo_handoff || '',
      ultima_mensagem_usuario: historico.length
        ? String(historico[historico.length - 1]?.resposta || '')
        : '',
      historico_consolidado: historicoTexto,
      criado_em: new Date().toISOString(),
    }
  }
];

const ctx = $json.contexto || {};
const historico = Array.isArray(ctx.historico_qa) ? ctx.historico_qa : [];

const formatarMySQLDateTime = (valor) => {
  const texto = String(valor || '').trim();
  if (!texto) return null;

  const match = texto.match(/^(\d{4}-\d{2}-\d{2}) (\d{2}:\d{2}:\d{2})/);
  if (match) {
    return `${match[1]} ${match[2]}`;
  }

  const data = new Date(texto);
  if (Number.isNaN(data.getTime())) return null;

  const pad = (n) => String(n).padStart(2, '0');

  return `${data.getFullYear()}-${pad(data.getMonth() + 1)}-${pad(data.getDate())} ${pad(data.getHours())}:${pad(data.getMinutes())}:${pad(data.getSeconds())}`;
};

return historico.map((item, index) => ({
  json: {
    session_id: $json.id || '',
    telefone: $json.telefone || ctx.wa_id || '',
    ordem: index + 1,
    etapa: item?.etapa || '',
    pergunta: item?.pergunta || '',
    resposta: item?.resposta || '',
    registrado_em: formatarMySQLDateTime(item?.registrado_em),
    campanha_nome: ctx.campanha_nome || '',
    template: ctx.template || '',
    motivo_handoff: ctx.motivo_handoff || '',
  }
}));

